-- Enrichment Batch 34 (2026-10-29): NEW 994 UBC Outstanding International Student Award (OIS);
-- UPLIFT 602 UBC IMES rel 8->10; micro-repairs 687 SGS@Tongji (rel 9 retained), 541 GT-IF
-- (rel 7 retained), 44 SGS pointer. Sources 3154/3155 (UBC) + 3156 (SGS guide) minted;
-- links 428-432; us 47 rewritten, us 198/228 synced, us 712 added. Notes appends replay-once.
-- BASELINE NOTE: this batch opened at 536 active / 205 retired (8 records had been deactivated
-- externally since Pass 127 without last_updated_at changing) and a PARALLEL session added
-- records 995-998 during the batch. Batch-attributable end state 537/205/1/199; live counters
-- at doc time 541/205/1/203, max 998/3156/716/432. Final setvals below use MAX(id) so they
-- stay correct under the parallel writes.
-- Evidence (fetched first-hand 2026-10-29): you.ubc.ca international awards page (IMES 2026/27
-- CAD 10,000-25,000/yr renewable; OIS 2025/26 CAD 10,000-25,000 one-time; automatic, no numeric
-- cutoffs, merit-only, not full cost; decisions mid-Feb-Apr) + UBC dates page (application
-- opened early Oct 2026; deadline 15 Jan 2027; ELAS docs 15 Feb 2027). Shanghai MEC guide
-- (Type A/B, ages 25/35/40 + pre-college <23, Feb-Apr window, annual evaluation; language bar
-- generic and amounts image-only). CTU host and UM aasd still unreachable (no writes).

-- 1) Sources 3154-3156
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified) VALUES (3154, 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', 'UBC Undergraduate Programs and Admissions — Scholarships and awards for international students (IMES, OIS, International Scholars, Okanagan awards)', 'you.ubc.ca', 'scholarship', '2026-10-29', true, true), (3155, 'https://you.ubc.ca/applying-ubc/dates-deadlines/', 'UBC Undergraduate Programs and Admissions — Dates and deadlines (Winter Session September 2027 cycle)', 'you.ubc.ca', 'scholarship', '2026-10-29', true, true), (3156, 'https://edu.sh.gov.cn/study_en_scholarships/20240904/5d8add31c7ce44a4b1e0d5bdfafe1495.html', 'Shanghai Municipal Education Commission (Study in Shanghai) — Application Guide to Shanghai Government Scholarship for International Students', 'edu.sh.gov.cn', 'scholarship', '2026-10-29', true, true)
