-- 2) NEW scholarship 994 (OIS)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (994, 'Outstanding International Student Award (OIS)', 'University of British Columbia (UBC)', 'Canada', 'Partial Tuition', 0, 'No separate scholarship application — apply for UBC admission by the application deadline (15 January 2027, 11:59 p.m. PST, for September 2027 entry) to be considered automatically; OIS announcements run March–April 2027.', '["Bachelor''s"]', '["All Majors"]', NULL, NULL, false, true, 'The Outstanding International Student (OIS) Award is a one-time, merit-based entrance scholarship that UBC offers to qualified international students when they are offered admission. For the 2025/26 academic year UBC valued OIS awards at CAD 10,000 to CAD 25,000, paid once; unlike the renewable International Major Entrance Scholarship (record 602) the OIS is not renewable, and unlike IMES it is also open to students entering UBC from post-secondary study, not only directly from secondary school. All international undergraduate applicants are automatically considered for the OIS and IMES after receiving an offer of admission — there is no separate scholarship form — and evaluation is based on the academic record and the personal profile. UBC states that OIS and IMES are merit-based only, cannot take financial need into consideration and do not cover the full cost of education, so recipients are expected to build a financial plan for the whole degree.', 'Be new to UBC, entering directly from secondary school or from post-secondary (university or college); be an international student who will study at UBC on a Canadian study permit (a change of citizenship status affects eligibility); demonstrate outstanding academic achievement and strong extracurricular involvement; and not be nominated for a need-and-merit-based International Scholars Program award. Consideration is automatic: apply to UBC by the admissions deadline and you are evaluated after you receive an offer of admission. Scholarship decisions are made between mid-February and the end of April; only successful recipients are notified, in advance of their admission acceptance deadline (1 May for most students), and award offers are final.', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', '["All"]', 'Merit-based', 'One-time entrance award of CAD 10,000–25,000 (2025/26 published values); not renewable and does not cover the full cost of a UBC degree.', NULL, NULL, NULL, NULL, 'No scholarship-specific English score is published; applicants must meet UBC''s English Language Admission Standard (ELAS) for their programme (ELAS documents are due by 15 February 2027 in the current cycle).', '["UBC admission application including the Personal Profile (no separate scholarship form)","Secondary-school or post-secondary transcripts as UBC requires for admission","Evidence of English language competency under UBC''s English Language Admission Standard"]', 'https://you.ubc.ca/apply/', NULL, '2027-01-15', 'automatic', NULL, NULL, '[]', 'annual', 'Early October each year (UBC online application opens for the next Winter Session)', 'Mid-January each year (UBC application deadline; 15 January 2027 for September 2027 entry)', 'open', '2026-10-29 19:00:00+05', '2026-10-29 19:00:00+05', 'verified', 10, 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', 'NEW in Enrichment Batch 34 (2026-10-29), written first-hand from UBC''s official "Scholarships and awards for international students" page and its dates-and-deadlines page (sources 3154/3155), both fetched 2026-10-29. The OIS is the one-time sibling of the renewable IMES (record 602) and was missing from the catalogue. deadline_date stores the operative date — the UBC application deadline of 15 January 2027 for September 2027 entry — because consideration is automatic on admission; the application opened in early October 2026, hence status=open. Values are a published range, so award_amount stays NULL with CAD / one_time / variable, and the page labels the CAD 10,000–25,000 range as its 2025/26 values. No GPA or IELTS cutoff is published for the award, so minima stay NULL; English is governed by UBC''s programme-level English Language Admission Standard. The Okanagan automatic awards on the same page (Global Elevation CAD 8,000, International Welcome CAD 5,000, BCom Launch CAD 6,000) were not catalogued in this batch.', true, 49, NULL, 'CAD', 'one_time', 'variable');

-- 3) Uplift 602 (rel 8->10; notes append: replay once)
UPDATE scholarships SET degree_levels = '["Bachelor''s"]', min_gpa = NULL, min_ielts = NULL, english_requirements = 'No scholarship-specific English score is published; applicants must meet UBC''s English Language Admission Standard (ELAS) for their programme (ELAS documents are due by 15 February 2027 in the current cycle).', requirements = requirements || ' Scholarship decisions are made between mid-February and the end of April; only successful recipients are notified, and the award offer must be accepted by the admission acceptance deadline (1 May for most students).', deadline = 'No separate scholarship application — apply for UBC admission by the application deadline (15 January 2027, 11:59 p.m. PST, for September 2027 entry) to be considered automatically; IMES decisions are made between mid-February and the end of April.', deadline_date = '2027-01-15', application_status = 'open', expected_opening_period = 'Early October each year (UBC online application opens for the next Winter Session)', expected_deadline_period = 'Mid-January each year (UBC application deadline; 15 January 2027 for September 2027 entry)', award_amount = NULL, award_currency = 'CAD', award_period = 'year', award_basis = 'variable', tuition_coverage = 'CAD 10,000–25,000 per year (2026/27 published values), renewable for up to three additional years; merit-based only and does not cover the full cost of a UBC degree.', accommodation = NULL, source_reliability = 10, last_verified_at = '2026-10-29 19:00:00+05', last_updated_at = '2026-10-29 19:00:00+05', notes = COALESCE(notes, '') || ' UPLIFTED to reliability 10 in Enrichment Batch 34 on 2026-10-29 after a first-hand re-read of UBC''s international awards page and dates-and-deadlines page (sources 3154/3155, minted and linked today). Corrections in this uplift: the imported min_gpa 3.6 and min_ielts 7 were deleted (UBC publishes no numeric cutoffs for IMES; English is governed by the programme-level English Language Admission Standard), degree_levels normalised to Bachelor''s, and the structured award moved from a single top-of-range figure (25,000 / range) to the catalogue convention for published ranges (amount NULL, CAD/year, basis variable) — the CAD 10,000–25,000 range stays in the text. The operative deadline is now stored in deadline_date: the UBC application deadline of 15 January 2027 (application opened early October 2026, so the cycle is open), with award decisions from mid-February to April. The one-time sibling award OIS was added as record 994 in the same batch.' WHERE id = 602;

-- 4) Micro-repair 687 (rel stays 9; notes append: replay once)
UPDATE scholarships SET min_gpa = NULL, min_ielts = NULL, application_status = 'upcoming', expected_opening_period = 'February to April each year (municipal window; each Shanghai university sets its own exact dates)', accommodation = NULL, last_verified_at = '2026-10-29 19:00:00+05', last_updated_at = '2026-10-29 19:00:00+05', notes = COALESCE(notes, '') || ' BATCH 34 MICRO-REPAIR 2026-10-29: the Shanghai Municipal Education Commission''s SGS application guide was re-fetched first-hand today and minted as source 3156 (this record previously had no sources-table row; link added in the same batch). The guide confirms the Type A (tuition, accommodation, living expenses, medical insurance) / Type B (tuition and medical insurance) split, the 25/35/40 age limits with a pre-college route under 23, the February-to-April application window on the Study in Shanghai portal, the ban on holding another Chinese government/organisational scholarship, first-year accommodation in principle, and the annual comprehensive evaluation that gates each following year of funding. Two limits of today''s read: the guide''s current text states the language bar generically (generally HSK4 plus the host university/programme requirements) and prints the coverage amounts only in an image appendix, so this record''s more specific language thresholds (HSK 5 with 210 / HSK 6 with 180 / IELTS 6.5 / TOEFL 90), stipend figures and the CSCA note still rest on the 2026-10-23 read and were NOT re-confirmed today; reliability therefore stays at 9 pending a readable current Tongji call. min_gpa 3.4 and min_ielts 6.5 were NULLed (no scheme-wide published cutoffs; the bars are programme-level and remain in the text), and status set to upcoming on the confirmed annual window.' WHERE id = 687;

-- 5) Micro-repair 541 (rel stays 7; notes append: replay once)
UPDATE scholarships SET application_url = 'https://sagata.itb.ac.id/index.php/login', expected_deadline_period = 'ITB lists the fellowship on partnership.itb.ac.id with the deadline marked to be announced (the old sps.itb.ac.id/gta address has been dead since the graduate-school restructure into SPITM; applications run through the sagata portal); the KNB national route opens in February and closes at the end of March.', last_verified_at = '2026-10-29 19:00:00+05', last_updated_at = '2026-10-29 19:00:00+05', notes = COALESCE(notes, '') || ' BATCH 34 MICRO-REPAIR 2026-10-29: ITB''s partnership scholarships page (source 3142) was re-fetched first-hand today and still lists the Ganesha Talent-International Fellowship as ITB-funded for master''s and doctoral programmes, typically covering tuition and possibly a living allowance depending on programme structure and qualifications, with the deadline to be announced. The page''s GT-IF official-site link leads to the sagata admissions login, while sps.itb.ac.id/gta still lands on a SPITM 404, so no current-call terms could be read and reliability stays at 7. application_url previously pointed at the KNB information page — a different, national scheme — and now points to the sagata portal the partnership page itself links for GT-IF.' WHERE id = 541;

-- 6) Micro-repair 44 (pointer now cites record 687; notes append: replay once)
UPDATE scholarships SET requirements = REPLACE(requirements, 'it is not part of the CSC award recorded here.', 'it is not part of the CSC award recorded here (the Shanghai Government Scholarship is catalogued separately at record 687).'), last_updated_at = '2026-10-29 19:00:00+05', notes = COALESCE(notes, '') || ' Batch 34 (2026-10-29) pointer repair: the SGS mention in requirements now cites the catalogue''s Shanghai Government Scholarship record (687, at Tongji University). No terms changed; reliability and last_verified_at unchanged.' WHERE id = 44;

