UPDATE university_scholarships SET availability_status = 'available', max_scholarship = 'CAD 10,000–25,000 per year, renewable for up to three additional years (2026/27 values); does not cover the full cost of a degree', covers_tuition = true, covers_living_expenses = false, valued_aspect = 'Academic achievement & Personal Profile (extracurricular involvement)', eligibility_notes = 'New international undergraduates entering UBC directly from secondary school on a Canadian study permit; automatic consideration on admission (apply by 15 January 2027 for September 2027 entry); exceptional academic achievement and extracurricular involvement; not open to International Scholars Program nominees; no published GPA or IELTS cutoff (UBC''s English Language Admission Standard applies).', official_url = 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', source_url = 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', last_verified_at = '2026-10-29 19:00:00+05' WHERE id = 47;
